"""Original GUI command symbols; vendor documentation informs meaning only."""
from core import p,r,c,accent,fill,PALE,TEAL,AMBER
ITEMS=[]
def add(id,en,ja,desc,jdesc,alias,body,family='feature'):
 ITEMS.append(dict(id=id,name=en,nameJa=ja,description=desc,descriptionJa=jdesc,family=family,role='command',tags=[family,'CAD',ja],aliases=[alias],sources=['solidcraft-commands'],body=body))
add('boundary-fill','Boundary fill','境界充填','Create a solid cell enclosed by intersecting boundaries.','交差する境界に囲まれたセルからソリッドを作成します。','solid.boundary_fill',p('M4 8 H28 M4 24 H28 M8 4 V28 M24 4 V28')+r(8,8,16,16,0,fill=PALE)+accent('M12 16 15 19 21 13'))
add('emboss','Emboss','エンボス','Raise or recess a profile on a target face.','対象面上の輪郭を浮き出しまたは彫り込みます。','solid.emboss',fill('M4 10 Q16 3 28 10 V25 Q16 18 4 25Z')+p('M11 12 17 10 21 12 V19 L15 21 11 19Z',fill='white')+accent('M11 12 15 14 21 12 M15 14 V21'))
add('pattern-path','Pattern along path','パス配列','Repeat a feature or body along a selected curve.','選択した曲線に沿ってフィーチャやボディを配列します。','solid.pattern.path',p('M4 27 Q7 6 28 6',stroke_dasharray='2 3')+r(3,20,7,7,1,fill=PALE)+r(10,9,7,7,1,fill=PALE)+r(22,3,7,7,1,fill=PALE))
add('mounting-boss','Mounting boss','取付ボス','Create a supported mounting boss for a plastic part.','樹脂部品に支持リブ付きの取付ボスを作成します。','plastic.boss',p('M4 27 H28 M10 24 5 27 M22 24 27 27')+fill('M10 10 Q16 5 22 10 V24 Q16 29 10 24Z')+p('M10 10 Q16 15 22 10')+p('M13 10 Q16 7 19 10 Q16 13 13 10',stroke=TEAL))
