add('snap-fit','Snap fit','スナップフィット','Create a flexible hook that latches into a mating recess.','相手側の凹部に係合する弾性フックを作成します。','plastic.snap_fit',fill('M5 27 V8 H10 V20 H23 V15 L29 22 V25 H10 V27Z')+p('M17 4 H28 V10 H23')+accent('M17 16 V7 M14 10 17 7 20 10'))
add('configuration-table','Configuration table','コンフィギュレーション表','Display parameter combinations and current state across named model configurations.','名前付きモデル構成ごとのパラメータ組合せと現在の状態を表で確認します。','config.table',r(3,5,26,23,1)+p('M3 12 H29 M11 5 V28 M20 12 V28 M3 20 H29')+r(12,13,7,6,0,fill=PALE,stroke='none')+accent('M5 8 H8 M14 8 H24'), 'configuration')
add('history-rollback','Roll back history','履歴ロールバック','Move the active history position back before later features.','後続フィーチャより前へ有効な履歴位置を戻します。','timeline.rollback',p('M8 4 V28 M8 7 H15 M8 16 H15 M8 25 H15',stroke_dasharray='2 2')+c(8,7,2,fill=PALE)+c(8,16,2,fill=PALE)+accent('M26 25 V12 Q26 7 21 7 H18 M21 4 18 7 21 10')+p('M3 20 H17',stroke=TEAL), 'history')
add('curvature-comb','Curvature comb','曲率コーム','Display curvature magnitude as normal comb teeth along a curve.','曲線の法線方向の櫛状線で曲率の大きさを表示します。','inspect.curvature_comb',p('M4 25 Q16 9 28 25')+accent('M7 22 4 17 M11 19 8 10 M16 17 V4 M21 19 24 10 M25 22 28 17'), 'inspection')
